mapper.select:
SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_mcp_server
WHERE status_cd = '00A'
  AND server_name = #{dto.serverName}

  AND server_id != #{dto.serverId}



  AND (
    tenant_id = -1
    OR (tenant_id = #{dto.tenantId} AND data_from = '10A' AND creator_id = #{userId})
  )


  AND tenant_id IN (#{dto.tenantId}, -1)

SELECT a.server_id, a.server_name, a.server_desc, a.server_type, a.server_url FROM bt_mcp_server a WHERE a.server_id IN
#{serverId}
AND a.status_cd = '00A' AND a.tenant_id IN (#{tenantId}, -1)

SELECT server_id, server_name, server_type, tenant_id
FROM bt_mcp_server
WHERE status_cd = '00A'
  AND server_effect = '1'
  AND tenant_id IN (#{query.tenantId}, -1)
  AND data_from is null

  AND server_type = #{query.serverType}


  AND catalog_item_id = #{query.catalogItemId}


  AND server_name LIKE #{query.searchContent}
